    <div class="w-full sm:max-w-2xl bg-[#161c33] border border-slate-700/80 rounded-t-2xl sm:rounded-2xl shadow-2xl overflow-hidden max-h-[92dvh] flex flex-col mb-[env(safe-area-inset-bottom)] sm:mb-0">
      <div class="px-5 py-3.5 bg-[#111629] border-b border-slate-700/60 flex items-center justify-between">
        <h3 id="drawerModalTitle" class="text-base font-bold text-white flex items-center gap-2">Panel de trabajo</h3>
        <button id="btnCloseDrawer" title="Cerrar panel" aria-label="Cerrar panel" class="p-1 rounded-lg text-slate-400 hover:text-white hover:bg-slate-800">
          <svg class="w-5 h-5" fill="none" stroke="currentColor" stroke-width="2" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" d="M6 18L18 6M6 6l12 12"/></svg>
        </button>
      </div>
      <div id="drawerModalBody" class="p-5 overflow-y-auto space-y-4 text-sm text-slate-200"></div>
    </div>
  </div>

  <!-- MODAL DEL MOTOR DE PRUEBA DE NOVELA VISUAL (pantalla completa estilo teléfono) -->
  <div id="playtestModal" class="hidden fixed inset-0 bg-black/90 backdrop-blur-md z-50 flex items-stretch sm:items-center justify-center p-0 sm:p-4">
    <div class="relative w-full sm:max-w-[430px] h-[100dvh] sm:h-[88vh] sm:max-h-[880px] bg-[#0c1021] sm:rounded-[1.8rem] overflow-hidden flex flex-col justify-between border-0 sm:border-2 border-cyan-400/50 sm:shadow-[0_0_50px_rgba(0,242,254,0.22)]">
      <!-- Dynamic Scene Background -->
      <div id="vnStageBg" class="absolute inset-0 bg-cover bg-center transition-all duration-500" style="background: radial-gradient(circle at 50% 35%, #283666 0%, #0d1226 100%);">
        <div class="absolute inset-0 bg-gradient-to-t from-[#080b18] via-transparent to-black/40"></div>
      </div>

      <!-- Top HUD inside Player -->
      <div class="relative z-20 flex flex-wrap items-center justify-between gap-2 px-3 sm:px-4 py-3 bg-gradient-to-b from-black/80 to-transparent">
        <div class="flex items-center gap-2">
          <span class="px-2.5 py-0.5 rounded-full text-[11px] font-semibold bg-emerald-500/20 text-emerald-300 border border-emerald-400/40 flex items-center gap-1.5">
            <span class="w-2 h-2 rounded-full bg-emerald-400 animate-pulse"></span>
            PRUEBA EN VIVO
          </span>
          <span id="vnCurrentNodeBadge" class="text-xs text-slate-300 font-medium truncate max-w-[140px]">Escena inicial 1</span>
        </div>
        <div class="flex items-center gap-2">
          <button id="btnVnRestart" class="px-2.5 py-1 rounded-lg bg-slate-800/80 hover:bg-slate-700 text-xs text-slate-200 border border-slate-600/50 transition">
            Reiniciar historia
          </button>
          <button id="btnVnToggleAudio" class="px-2.5 py-1 rounded-lg bg-slate-800/80 hover:bg-slate-700 text-xs text-cyan-300 border border-slate-600/50 transition">
            🔊 Sonido activado
          </button>
          <button id="btnClosePlaytest" class="px-3 py-1 rounded-lg bg-rose-500/80 hover:bg-rose-500 text-xs font-semibold text-white transition">
            Salir de la vista previa
          </button>
        </div>
      </div>

      <!-- Center Character Sprite & Branching Choices Layer -->
      <div class="relative z-10 flex-1 flex items-center justify-center pointer-events-none px-4 min-h-0">
        <div id="vnSpriteContainer" class="transition-all duration-300 flex flex-col items-center max-h-full">
          <img id="vnCharacterSprite" class="max-h-[38vh] sm:max-h-[34vh] w-auto max-w-full object-contain rounded-2xl border border-white/15 shadow-2xl" src="data:image/jpeg;base64," alt="Personaje" />
        </div>

        <!-- Choice Overlay Buttons when on a Choice Node or Scene with Choices -->
        <div id="vnChoicesOverlay" class="hidden absolute inset-0 bg-black/45 backdrop-blur-[2px] flex flex-col items-center justify-center gap-3 p-6 pointer-events-auto overflow-y-auto"></div>
      </div>

      <!-- Bottom Visual Novel Dialogue Box -->
      <div class="relative z-20 p-3 sm:p-4 pb-[max(0.75rem,env(safe-area-inset-bottom))]">
        <div class="bg-[#12172d]/95 border border-cyan-400/40 rounded-2xl p-4 sm:p-5 shadow-2xl backdrop-blur-md">
          <div class="flex items-center justify-between mb-1.5">
            <span id="vnSpeakerName" class="text-sm sm:text-base font-bold text-rose-400 tracking-wide">Sora</span>
            <span id="vnExpressionTag" class="text-[11px] text-slate-400">Alegre • Escala 100%</span>
          </div>
          <p id="vnDialogueText" class="text-sm sm:text-base text-slate-100 leading-relaxed min-h-[2.75rem]">
            ¡Hola! Qué bueno que llegaste. ¿A dónde vamos?
          </p>
          <div class="mt-3 flex items-center justify-between border-t border-slate-800/80 pt-2.5">
            <div id="vnVariablesReadout" class="text-[11px] text-slate-400 flex items-center gap-3"></div>
            <button id="btnVnNext" class="flex items-center gap-1.5 px-4 py-1.5 rounded-xl bg-gradient-to-r from-cyan-500 to-indigo-500 hover:from-cyan-400 hover:to-indigo-400 text-xs sm:text-sm font-semibold text-slate-950 shadow-lg transition">
              <span>Continuar</span>
              <svg class="w-4 h-4" fill="none" stroke="currentColor" stroke-width="2.5" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" d="M9 5l7 7-7 7"/></svg>
            </button>
          </div>
        </div>
      </div>
    </div>
  </div>

  <!-- PANTALLA DE CARGA DEL NIVEL COMPARTIDO -->
  <div id="shareLoading" class="hidden fixed inset-0 z-[90] bg-[#0b0f1f] flex-col items-center justify-center gap-5 p-8 text-center">
    <div class="share-loader-spin" aria-hidden="true"></div>
    <div>
      <div class="text-lg font-bold text-white">Cargando tu nivel…</div>
      <div id="shareLoadingMsg" class="text-sm text-slate-400 mt-1">Conectando con la historia</div>
    </div>
    <div class="w-full max-w-xs h-2 rounded-full bg-slate-800 overflow-hidden">
      <div id="shareLoadingBar" class="h-full w-[5%] rounded-full bg-gradient-to-r from-cyan-400 to-indigo-500"></div>
    </div>
    <div id="shareLoadingGame" class="text-xs text-slate-500">Preparando escenario a pantalla completa</div>
  </div>

  <!-- NOTIFICACIÓN FLOTANTE -->
  <div id="toastBanner" class="fixed top-16 right-4 z-50 hidden px-4 py-2.5 rounded-xl bg-[#18203c] border border-cyan-400/60 text-xs sm:text-sm text-cyan-200 shadow-2xl flex items-center gap-2">
    <span class="w-2 h-2 rounded-full bg-cyan-400"></span>
    <span id="toastMessage">¡Guardado!</span>
  </div>
</div>
